from scipy.optimize import least_squares
e=np.asarray(eps,float); t=np.asarray(T,float); y=np.asarray(sigma,float)
d=0.75611
g=e*np.exp(-d*e)/t
basis={'1':np.ones_like(t),'T':t,'T2':t**2,'1/T':1/t,'T3':t**3,'1/T2':1/t**2,'logT':np.log(t),'expm/T':np.exp(-43/t),'T^-3':t**-3,'sqrtT':np.sqrt(t)}
names=list(basis)
def fit(names):
    X=np.column_stack([basis[n] for n in names]+[g])
    c,*_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c
    return c, (r**2).mean()/y.var()
for combo in [['1','T','T2','1/T'],['1','T','T2','1/T','expm/T'],['1','T','T2','1/T','T3'],['1','T','T2','1/T','1/T2'],['1','T','T2','1/T','logT'],['1','T','1/T','1/T2','T3'],['1','T','T2','1/T','T3','1/T2']]:
    c,nm=fit(combo); print(combo, nm, np.round(c,4))
